require_once __DIR__.'/includes/functions.php';require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/csrf.php';$u=require_login();$listingId=(int)($_GET['listing_id']??$_POST['listing_id']??0);$pdo=db();$check=$pdo->prepare("SELECT l.id,l.user_id FROM listings l JOIN users seller ON seller.id=l.user_id WHERE l.id=? AND l.status='approved' AND l.availability_status IN ('available','reserved') AND seller.is_active=1 LIMIT 1");$check->execute([$listingId]);$listing=$check->fetch();if(!$listing||(int)$listing['user_id']===(int)$u['id']){http_response_code(404);exit('Listing is not available for reporting.');}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$reason=(string)($_POST['reason']??'Other');$allowed=['Scam','Fake product','Suspicious price','Reused image','Prohibited item','Misleading description','Other'];if(!in_array($reason,$allowed,true))$reason='Other';$description=trim((string)($_POST['description']??''));if(mb_strlen($description)>2000){flash('error','Report details must be 2000 characters or fewer.');}else{try{$s=$pdo->prepare('INSERT INTO reports(listing_id,reporter_id,reason,description) VALUES(?,?,?,?)');$s->execute([$listingId,$u['id'],$reason,$description]);flash('success','Report submitted for admin review.');redirect('/listing.php?id='.$listingId);}catch(PDOException$e){flash('error',$e->getCode()==='23000'?'You already reported this listing.':'Report could not be submitted.');}}}
$pageTitle='Report listing';include __DIR__.'/includes/header.php';?><form class="form-card" method="post"><h1>Report suspicious listing</h1><p class="muted">Reports go to human moderation. They do not automatically prove fraud.</p><?=csrf_field()?><input type="hidden" name="listing_id" value="<?=$listingId?>"><div class="stack"><div class="field"><label>Reason</label><select name="reason"><?php foreach(['Scam','Fake product','Suspicious price','Reused image','Prohibited item','Misleading description','Other']as$r):?><option><?=e($r)?></option><?php endforeach;?></select></div><div class="field"><label>Details</label><textarea name="description" maxlength="2000"></textarea></div><button class="btn">Submit report</button></div></form><?php include __DIR__.'/includes/footer.php';?>
